function bibleYearDayNumber(d){const y=d.getFullYear(),start=new Date(y,0,1),day=Math.floor((new Date(y,d.getMonth(),d.getDate())-start)/86400000)+1;return Math.min(day,365)}
function bibleYearPlan(day){const total=BIBLE_YEAR_CHAPTERS.length,start=Math.floor((day-1)*total/365),end=Math.floor(day*total/365),parts=BIBLE_YEAR_CHAPTERS.slice(start,end);const groups=[];for(const p of parts){const last=groups[groups.length-1];if(last&&last.book===p.book&&last.to===p.chapter-1)last.to=p.chapter;else groups.push({book:p.book,from:p.chapter,to:p.chapter})}return groups}
function bibleYearRef(groups){return groups.map(g=>g.book+" "+g.from+(g.to>g.from?"-"+g.to:"")).join("; ")}
async function loadBibleYear(d){
 const day=bibleYearDayNumber(d),groups=bibleYearPlan(day),ref=bibleYearRef(groups),dayEl=$("#bibleYearDay"),refEl=$("#bibleYearRef"),textEl=$("#bibleYearText"),btn=$("#bibleMarkRead");
 if(!dayEl)return;dayEl.textContent="Giorno "+day+" di 365";refEl.textContent=ref;textEl.innerHTML='<div class="status">Caricamento CEI 2008…</div>';
 const key="bibleyear:cei2008:"+ref;let html=localStorage.getItem(key)||"";
 if(!html){try{const chunks=[];for(const g of groups){const q=g.book+" "+g.from+(g.to>g.from?"-"+g.to:"");const u="https://query.bibleget.io/v3/?query="+encodeURIComponent(q)+"&version=CEI2008&return=json&appid=calendario-cattolico";const r=await fetch(u);if(!r.ok)throw Error("BibleGet");const data=await r.json(),vv=data.verses||data.results||data;if(Array.isArray(vv))chunks.push('<section class="bible-chunk"><h4>'+esc(q)+'</h4>'+vv.map(v=>'<p><sup>'+esc(v.verse??v.versenum??v.verse_number??"")+'</sup> '+esc(v.text??v.verse_text??v.content??"")+'</p>').join("")+'</section>')}html=chunks.join("");if(html)localStorage.setItem(key,html)}catch(e){console.warn("Bibbia in un anno:",e)}}
 textEl.innerHTML=html||'<p>Il testo non è disponibile in questo momento. Riprova quando sei online.</p>';
 const read=JSON.parse(localStorage.getItem("bibleYearRead")||"{}"),k=d.getFullYear()+"-"+day;btn.classList.toggle("done",!!read[k]);btn.textContent=read[k]?"✓ Letto":"✓ Segna come letto";
 btn.onclick=()=>{const rr=JSON.parse(localStorage.getItem("bibleYearRead")||"{}");rr[k]=!rr[k];localStorage.setItem("bibleYearRead",JSON.stringify(rr));loadBibleYear(d)};
 const count=Object.keys(read).filter(k=>k.startsWith(d.getFullYear()+"-")&&read[k]).length,pct=Math.round(count/365*100);$("#bibleProgressText").textContent=count+"/365 giorni letti • "+pct+"%";$("#bibleProgressBar").style.width=pct+"%";
}
const Narrator=(()=>{let audio=null,active=null;
const PREGENERATED_BASE="/audio/nicola/";
function clean(el){return (el?.innerText||el?.textContent||"").replace(/\s+/g," ").trim()}
function safeKey(btn){const d=new Date(window.selectedDate||Date.now()),day=[d.getFullYear(),String(d.getMonth()+1).padStart(2,"0"),String(d.getDate()).padStart(2,"0")].join("-");return day+"-"+btn.dataset.read+".mp3"}
async function prerecorded(btn){const url=PREGENERATED_BASE+safeKey(btn);try{const r=await fetch(url,{method:"HEAD",cache:"force-cache"});return r.ok?url:null}catch(e){return null}}
async function generate(text){const endpoint="https://leonelhs-kokoro-tts-italian.hf.space/gradio_api/call/predict";const first=await fetch(endpoint,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({data:[text,"im_nicola",0.92]})});if(!first.ok)throw Error("Servizio narratore non disponibile");const j=await first.json();if(!j.event_id)throw Error("Risposta narratore non valida");const r=await fetch(endpoint+"/"+j.event_id);if(!r.ok)throw Error("Audio non disponibile");const raw=await r.text();for(const line of raw.split("\n").filter(x=>x.startsWith("data: "))){try{const data=JSON.parse(line.slice(6)),v=Array.isArray(data)?data[0]:data;if(v?.url)return v.url;if(v?.path&&/^https?:/.test(v.path))return v.path}catch(e){}}throw Error("Audio non ricevuto")}
function reset(){document.querySelectorAll(".narrate-btn").forEach(b=>{b.innerHTML='<span class="play-icon">▶</span><span class="play-label">Ascolta</span>';b.classList.remove("playing")});active=null}
async function play(btn){if(active===btn&&audio&&!audio.paused){audio.pause();btn.innerHTML='<span class="play-icon">▶</span><span class="play-label">Riprendi</span>';return}if(active===btn&&audio?.paused){await audio.play();btn.innerHTML='<span class="play-icon">⏸</span><span class="play-label">Pausa</span>';return}if(audio){audio.pause();audio=null}reset();const el=document.getElementById(btn.dataset.read),text=clean(el);if(!text)return;active=btn;btn.innerHTML='<span class="play-icon">⏳</span><span class="play-label">Preparo la voce…</span>';btn.disabled=true;try{if(typeof MeditationMusic!=="undefined")MeditationMusic.stop();const stored=await prerecorded(btn);const url=stored||await generate(text.slice(0,3500));audio=new Audio(url);audio.onended=reset;audio.onerror=reset;await audio.play();btn.textContent="⏸ Pausa";btn.classList.add("playing")}catch(e){console.warn("Narratore:",e);btn.innerHTML='<span class="play-icon">⚠</span><span class="play-label">Riprova</span>'}finally{btn.disabled=false}}
function init(){document.querySelectorAll(".narrate-btn").forEach(b=>b.addEventListener("click",()=>play(b)))}
return{init}})();
const MeditationMusic=(()=>{
let audio=null,playing=false;
const TRACK="https://upload.wikimedia.org/wikipedia/commons/transcoded/7/72/The_Tudor_Consort_-_03_-_Kyrie_Eleison.ogg/The_Tudor_Consort_-_03_-_Kyrie_Eleison.ogg.mp3";
const pref=()=>localStorage.getItem("meditationMusic");
function ensure(){if(audio)return;audio=new Audio(TRACK);audio.loop=true;audio.preload="metadata";audio.volume=.24;audio.addEventListener("ended",()=>{if(playing){audio.currentTime=0;audio.play().catch(()=>{})}})}
function update(){const b=document.querySelector("#musicToggle");if(b){b.textContent=playing?"♫":"♪";b.classList.toggle("playing",playing);b.setAttribute("aria-label",playing?"Disattiva canto sacro":"Attiva canto sacro")}}
async function start(){ensure();try{await audio.play();playing=true;update();return true}catch(e){console.warn("Audio sacro:",e);playing=false;update();return false}}
function stop(){playing=false;if(audio){audio.pause();audio.currentTime=0}update()}
async function init(){const modal=document.querySelector("#musicConsent");if(!modal)return;const p=pref();if(p===null)modal.hidden=false;else if(p==="on"){const once=async()=>{document.removeEventListener("pointerdown",once);await start()};document.addEventListener("pointerdown",once,{once:true})}
document.querySelector("#musicYes").onclick=async()=>{localStorage.setItem("meditationMusic","on");modal.hidden=true;await start()};
document.querySelector("#musicNo").onclick=()=>{localStorage.setItem("meditationMusic","off");modal.hidden=true;stop()};
document.querySelector("#musicToggle").onclick=async()=>{if(playing){localStorage.setItem("meditationMusic","off");stop()}else{localStorage.setItem("meditationMusic","on");await start()}}}
return{init,start,stop}})();
document.addEventListener("DOMContentLoaded",()=>{renderDay(new Date());renderCalendar();MeditationMusic.init();Narrator.init()});
